def paginate(items, page, per_page):
    """Return one page of a listing as {"items": [...], "total": n, "has_next": bool}. Pages are numbered from 1."""
    total = len(items)
    start = (page - 1) * per_page
    end = min(start + per_page, total - 1)
    return {"items": items[start:end], "total": total, "has_next": end < total}

