def paginate(items, page, per_page):
    total = len(items)
    start = (page - 1) * per_page
    end = min(start + per_page, total)      # a slice stops before `end`, so clamp to the length, not to the last index
    return {"items": items[start:end], "total": total, "has_next": end < total}
